import type {MouseEventHandler} from "react";
import {useState} from "react";

interface Entry {
  id: string;
  label: string;
}

export const EntriesPage = ({entries}: {entries: Entry[]}) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  /**
   * @event entry 선택 상태 토글
   */
  const handleSelectionToggle =
    (entryId: string): MouseEventHandler<HTMLButtonElement> =>
    (_event) => {
      setSelectedIds((currentSelectedIds) => {
        if (currentSelectedIds.includes(entryId)) {
          return currentSelectedIds.filter(
            (selectedId) => selectedId !== entryId,
          );
        }

        return [...currentSelectedIds, entryId];
      });
    };

  return (
    <section>
      <p>
        {selectedIds.length > 0
          ? `${selectedIds.length} selected`
          : "No selection"}
      </p>
      {entries.map((entry) => (
        <button
          key={entry.id}
          onClick={handleSelectionToggle(entry.id)}
        >
          {entry.label}
        </button>
      ))}
    </section>
  );
};
